use serde :: { Deserialize , Serialize } ; # [doc = " Status of a file in relation to the server"] # [derive (Debug , Clone , PartialEq , Eq , Serialize , Deserialize , PartialOrd , Ord)] pub enum SyncStatus { # [doc = " File is in sync with server (same hash)"] InSync , # [doc = " File has been modified locally"] Modified , # [doc = " File is new (not on server)"] New , # [doc = " File exists on server but not locally (deleted locally)"] Deleted , # [doc = " File could not be read locally (e.g. permission error, binary file)"] Failed , }